'use strict';
const $ = (selector) => document.querySelector(selector);
const escapeHTML = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE = 'texas-liberty-watch-90r-v1';
let local = {saved: [], notes: {}};
try { const parsed = JSON.parse(localStorage.getItem(STORE)); if (parsed && Array.isArray(parsed.saved) && parsed.notes && typeof parsed.notes === 'object') local = parsed; } catch {}
const state = {data: null, view: 'tracker', page: 1, pageSize: 10};
const reviewed = (bill) => bill.reviewState === 'Text reviewed';
const billSort = (a, b) => a.type.localeCompare(b.type) || Number(a.id.match(/\d+/)[0]) - Number(b.id.match(/\d+/)[0]);
const displayDate = (date, full = false) => new Intl.DateTimeFormat('en-US', {month:'short', day:'numeric', ...(full ? {year:'numeric'} : {}), timeZone:'America/Chicago'}).format(new Date(date.length === 10 ? date + 'T18:00:00Z' : date));
function persist() { try { localStorage.setItem(STORE, JSON.stringify(local)); return true; } catch { toast('Browser storage is unavailable. Export a backup to keep your work.'); return false; } }
let toastTimer;
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 3500); }
function setCounts() {
  $('#nav-total').textContent = state.data.bills.length;
  $('#stat-total').textContent = state.data.bills.length;
  $('#stat-reviewed').textContent = state.data.bills.filter(reviewed).length;
  const count = state.data.bills.filter(b => local.saved.includes(b.id)).length;
  $('#nav-saved').textContent = count; $('#stat-saved').textContent = count;
}
function filtered() {
  const query = $('#search').value.trim().toLocaleLowerCase();
  const compactQuery = query.replace(/\s/g, '');
  const topic = $('#topic').value, chamber = $('#chamber').value, review = $('#review').value;
  let bills = state.data.bills.filter(b => (!query || `${b.caption} ${b.title || ''} ${b.number} ${b.author} ${b.summary || ''} ${b.topics.join(' ')}`.toLocaleLowerCase().includes(query) || b.id.toLowerCase().includes(compactQuery)) && (!topic || b.topics.includes(topic)) && (!chamber || b.chamber === chamber) && (!review || (review === 'reviewed' ? reviewed(b) : !reviewed(b))) && (state.view !== 'watchlist' || local.saved.includes(b.id)));
  bills.sort((a,b) => {
    if ($('#sort').value === 'number') return billSort(a,b);
    if ($('#sort').value === 'review') return Number(reviewed(b))-Number(reviewed(a)) || billSort(a,b);
    return b.actionDate.localeCompare(a.actionDate) || Number(reviewed(b))-Number(reviewed(a)) || billSort(a,b);
  });
  return bills;
}
function renderBills() {
  if (!state.data) return;
  setCounts();
  const bills = filtered(), pages = Math.max(1, Math.ceil(bills.length / state.pageSize));
  state.page = Math.min(state.page, pages);
  const start = (state.page - 1) * state.pageSize;
  $('#results-count').textContent = `${bills.length} measure${bills.length === 1 ? '' : 's'}${state.view === 'watchlist' ? ' in your watchlist' : ' matching this view'}`;
  $('#list-title').textContent = state.view === 'watchlist' ? 'Your saved legislation' : 'Legislation to watch';
  const hasFilters = ['search','topic','chamber','review'].some(id => $('#'+id).value);
  $('#active-filters').hidden = !hasFilters;
  $('#bill-list').innerHTML = bills.length ? bills.slice(start,start+state.pageSize).map(b => {
    const saved = local.saved.includes(b.id);
    return `<article class="bill-row"><div class="bill-top"><button class="bill-number ${b.chamber === 'Senate' ? 'senate' : ''}" data-bill="${b.id}">${escapeHTML(b.number)}</button><span class="bill-author">${escapeHTML(b.author)}</span></div><button class="bill-open" data-bill="${b.id}"><span class="bill-title">${escapeHTML(b.title || b.caption.replace(/^Relating to /i, '').replace(/^./, c=>c.toUpperCase()))}</span></button><button class="save-bill ${saved?'saved':''}" data-save="${b.id}" aria-label="${saved?'Remove':'Save'} ${escapeHTML(b.number)}${saved?' from':' to'} watchlist" aria-pressed="${saved}">${saved?'★':'☆'}</button><div class="bill-meta"><span class="topic-tag">${escapeHTML(b.topics[0] || 'Further review')}</span><span class="meta-divider">·</span><span>${escapeHTML(b.lastAction.replace(/^[HSE]\s+/,'').slice(0,60))} ${displayDate(b.actionDate)}</span><span class="meta-divider">·</span><span class="${reviewed(b)?'review-dot':'review-needed'}">${reviewed(b)?'✓ Text reviewed':'○ Needs review'}</span></div><span class="row-arrow" aria-hidden="true">→</span></article>`;
  }).join('') : `<div class="empty"><span aria-hidden="true">☆</span><h3>${state.view==='watchlist'&&!local.saved.length ? 'Make this desk yours.' : 'No matching measures.'}</h3><p>${state.view==='watchlist'&&!local.saved.length ? 'Star a bill in the tracker to keep it here. Your watchlist and notes stay in this browser.' : 'Try another topic, author, or bill number, or clear the filters.'}</p><button class="button" ${hasFilters?'data-clear':'data-view="tracker"'}>${hasFilters?'Clear filters':'Explore the tracker'}</button></div>`;
  $('#pagination').innerHTML = bills.length ? `<span>${start+1}–${Math.min(start+state.pageSize,bills.length)} of ${bills.length}</span><div><button data-page="${state.page-1}" ${state.page===1?'disabled':''}>← Previous</button><button data-page="${state.page+1}" ${state.page===pages?'disabled':''}>Next →</button></div>` : '';
}
function clearFilters() { for (const id of ['search','topic','chamber','review']) $('#'+id).value=''; state.page=1;renderBills(); }
function navigate(view, updateHash=true) {
  if (!state.data) return;
  state.view = ['tracker','watchlist','activity','methodology','setup','about'].includes(view) ? view : 'tracker'; state.page=1;
  document.querySelectorAll('.nav-item[data-view]').forEach(el => {const active=el.dataset.view===state.view;el.classList.toggle('active',active); if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  const titles = {about:['About Eric Hudson.','Commercial trial lawyer.  Constitutional advocate.'],tracker:['Religious liberty, tracked.','A clear view of the bills that could shape freedom of faith in Texas.'],watchlist:['Your watchlist.','Keep the measures that matter to you close at hand.'],activity:['The latest on the radar.','A record of additions and changes detected by this tracker.'],methodology:['Know what you’re reading.','Official records, transparent screening, and a clear line between facts and analysis.'],setup:['Built to stay free.','A portable website you can host and update without a paid service.']};
  $('#page-title').textContent=titles[state.view][0];$('#page-description').textContent=titles[state.view][1];
  const isList = ['tracker','watchlist'].includes(state.view);
  $('#tracker-content').hidden=!isList; $('#other-content').hidden=isList; $('#export').hidden=!isList;
  if(isList)renderBills();else $('#other-content').innerHTML=state.view==='about'?about():state.view==='methodology'?methodology():state.view==='setup'?setup():activity();
  if(updateHash) history.replaceState(null,'','#'+state.view);
}
function about() {
  return `<div class="about-layout"><article class="content-card about-bio"><p class="eyebrow">THE LAWYER BEHIND THE TRACKER</p><h2>Eric A. Hudson</h2><p class="about-position">Partner · Arambula Terrazas PLLC · Austin, Texas</p><p class="about-lead">Eric Hudson is a litigation partner at Arambula Terrazas PLLC with nearly two decades of experience in commercial litigation, constitutional disputes, injunctions, and appeals.  He represents clients in state and federal courts and arbitration, including matters involving religious institutions and governmental action.</p><p>Before entering private practice, Eric served as Senior Special Counsel in the Texas Attorney General’s Special Litigation Unit, handling constitutional, election, and public-law litigation.  His practice combines trial advocacy with experience before the Texas Supreme Court, the Fifth Circuit, and the United States Supreme Court.</p><div class="about-practice"><span>Constitutional litigation</span><span>Religious liberty</span><span>Injunctions & emergency relief</span><span>Trials & appeals</span></div><div class="about-links"><a class="button primary" href="https://www.linkedin.com/in/txattorney" target="_blank" rel="noopener">Follow Eric on LinkedIn →</a><a class="button" href="https://www.atlawpllc.com/eric-hudson" target="_blank" rel="noopener">Read the firm biography →</a></div></article><aside><section class="contact-card"><p class="eyebrow">GET IN TOUCH</p><h2>Let’s connect.</h2><dl><dt>Email</dt><dd><a href="mailto:ehudson@atlawpllc.com">ehudson@atlawpllc.com</a></dd><dt>Direct phone</dt><dd><a href="tel:+15122949891">(512) 294-9891</a></dd><dt>Firm office</dt><dd><a href="tel:+15129040200">(512) 904-0200</a></dd><dt>Address</dt><dd>Arambula Terrazas PLLC<br>1001 S Capital of Texas Hwy<br>Building L, Suite 250<br>Austin, TX 78746</dd></dl><a class="text-button light" href="https://www.atlawpllc.com/" target="_blank" rel="noopener">Visit the firm <span>→</span></a></section><div class="about-source">Contact details from <a href="https://www.atlawpllc.com/eric-hudson" target="_blank" rel="noopener">Eric’s firm biography</a> and the <a href="https://www.atlawpllc.com/" target="_blank" rel="noopener">firm’s contact page</a>.</div></aside></div>`;
}
function methodology() {
  return `<div class="content-grid"><div><article class="content-card"><h2>What this tracker covers</h2><p>Religious liberty across faiths: religious exercise, conscience protections, schools and education, equal treatment, worship and land use, and measures affecting particular faith communities.</p><p>Each update screens the captions in Texas Legislature Online’s filed House and Senate reports for 90R. Bills, joint resolutions, and other resolutions can appear. A proposed constitutional amendment remains a proposal; it is not treated as an enacted law.</p><h3>Screening is a starting point</h3><p>Caption matching can miss relevant provisions buried in a bill. Broad matches, such as cemetery, municipal utility district, private-school, and nondiscrimination proposals, need a closer look. This is a focused review queue, not a claim that every relevant bill has been identified.</p><h3>Read the labels</h3><ul><li><strong>Caption screened:</strong> Official filing metadata is available; the connection is provisional. No substantive summary has been approved.</li><li><strong>Text reviewed:</strong> The identified text version has a plain-language summary and a separate editorial relevance note.</li><li><strong>Text changed:</strong> A version or text change requires another review. The old summary is withheld.</li></ul><p>Relevance notes identify issues to examine. They do not establish discriminatory intent, constitutionality, or the tracker owner’s position on a bill.</p></article><article class="content-card"><h2>How updates work</h2><p>${state.data.updateMode==='github-actions'?'This snapshot was published through the GitHub Actions workflow. Daily checks are configured through May 31, 2027; inspect the repository’s Actions page to confirm each run.':'The current site displays a stored snapshot. The downloadable package includes a daily GitHub Actions update that can be activated with free hosting. Until that is configured, this hosted copy does not refresh itself.'}</p><p>Once enabled, the updater reads both official filing reports, refreshes tracked measures, retrieves their latest available HTML text, and flags text changes. It preserves the prior snapshot if a report is missing, incomplete, or from the wrong session. Partial text retrieval failures appear on affected bills.</p><p>Schedules can run late. A snapshot older than 36 hours is labeled for refresh. Hearing notices, amendments, votes, and fiscal notes should be checked on the official bill pages; this version does not separately ingest them.</p></article></div><div><article class="content-card"><h2>The source record</h2><div class="coverage"><strong>${state.data.screenedCount.toLocaleString()}</strong><p>Official captions screened<br>${displayDate(state.data.updatedAt,true)}</p></div>${state.data.reports.map(r=>`<div class="source-record"><a href="${escapeHTML(r.url)}" target="_blank" rel="noopener">${escapeHTML(r.label)} →</a><span>${r.records.toLocaleString()} records · checked ${displayDate(r.checkedAt,true)}</span></div>`).join('')}<p>Bill histories and texts are linked in every detail panel. Data comes from Texas Legislature Online. This is an independent site.</p></article><article class="content-card"><h2>Session calendar</h2><p><a href="https://tlc.texas.gov/docs/legref/Dates-of-Interest.pdf" target="_blank" rel="noopener">Texas Legislative Council dates of interest →</a> identifies November 9, 2026 prefiling and January 12, 2027 opening day.</p><p>March 12 and May 31 are the calculated 60th and 140th days. See <a href="https://tcss.legis.texas.gov/resources/CN/htm/CN.3.htm" target="_blank" rel="noopener">Texas Constitution article III, sections 5 and 24 →</a>. Filing exceptions and any adopted 90R rules still matter.</p></article><article class="content-card"><h2>Your watchlist</h2><p>Stars and notes are stored on this browser. They are not uploaded to the website or shared between devices. Clearing browser storage removes them.</p><div class="download"><button class="button" data-backup>Download personal backup</button></div><div class="download"><label class="button">Restore personal backup<input type="file" id="restore-backup" accept="application/json,.json" hidden></label></div><p class="hint">A restore merges saved bills and replaces notes for matching bill numbers.</p></article></div></div>`;
}
function setup() {
  return `<div class="setup-status">${state.data.updateMode==='github-actions'?'This copy was published by the included workflow. Check GitHub Actions for the current schedule and run status.':'Daily updating is ready to configure. No GitHub or Cloudflare account has been connected by this site.'}</div><div class="content-grid"><div><article class="content-card"><p class="eyebrow">RECOMMENDED · GITHUB PAGES</p><h2>A free home for the tracker.</h2><p>Use a public GitHub repository and GitHub Pages. The package includes the website, current data, the source updater, and the workflow for a daily refresh.</p><ol><li><strong>Download and unzip the starter.</strong> Keep the <code>.github</code> folder; it contains the publishing and update workflow.</li><li><strong>Create a public repository</strong> in your free GitHub account. Upload the extracted contents, with <code>dist</code>, <code>scripts</code>, <code>editorial.json</code>, and <code>.github</code> at the repository root. The README includes Git commands if your upload tool hides dot-folders.</li><li><strong>Open Settings → Pages.</strong> Under Build and deployment, choose <strong>GitHub Actions</strong>.</li><li><strong>Open Actions → Publish and update 90R tracker.</strong> Choose <strong>Run workflow</strong>. Allow workflow write permissions if your account blocks committing data.</li><li><strong>Open the published link.</strong> GitHub provides a free <code>github.io</code> address. The included schedule checks daily at 13:37 UTC, which is 7:37 a.m. CST or 8:37 a.m. CDT, through May 31, 2027.</li></ol><div class="download"><a class="button primary" href="downloads/texas-liberty-watch-starter.zip" download>↓ Download website & setup guide</a></div><h3>Daily monitoring without AI charges</h3><p>The updater uses official reports and keyword screening. New matches enter as needing review. You control summaries in <code>editorial.json</code>; the program does not invent legal analysis.</p><p>A successful scheduled update commits data and publishes it in the same run. Scheduled workflows may be delayed, and GitHub disables scheduled workflows in public repositories after 60 days without repository activity. Check Actions periodically; the site also warns when data ages.</p></article><article class="content-card"><h2>Another free option: Cloudflare Pages</h2><p>Connect the same repository to Cloudflare Pages. Choose no framework, set the build command to <code>python3 scripts/package_starter.py</code>, and set the output directory to <code>dist</code>. Cloudflare supplies a free <code>pages.dev</code> address.</p><p>Keep the updater on GitHub, but disable the GitHub Pages deploy job as described in the README. Cloudflare publishes new data when the workflow commits it. A static upload by itself does not activate daily updates.</p></article></div><div><article class="content-card"><h2>The $0 setup</h2><div class="cost-row"><span>Static website hosting</span><strong>$0</strong></div><div class="cost-row"><span>Host-provided address</span><strong>$0</strong></div><div class="cost-row"><span>Official bill data</span><strong>$0</strong></div><div class="cost-row"><span>Daily public-repo workflow</span><strong>$0</strong></div><div class="cost-row"><span>AI API required</span><strong>No</strong></div><p style="margin-top:16px">A purchased custom domain is optional and usually costs money. Free services remain subject to provider limits and terms.</p></article><article class="content-card"><h2>Verified provider guidance</h2><p><a href="https://docs.github.com/en/pages/getting-started-with-github-pages/creating-a-github-pages-site" target="_blank" rel="noopener">GitHub Pages availability and setup →</a></p><p><a href="https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#schedule" target="_blank" rel="noopener">Scheduled workflow behavior →</a></p><p><a href="https://developers.cloudflare.com/pages/platform/limits/" target="_blank" rel="noopener">Cloudflare free-plan limits →</a></p><p><a href="https://developers.cloudflare.com/pages/framework-guides/deploy-anything/" target="_blank" rel="noopener">Cloudflare static site setup →</a></p></article></div></div>`;
}
function activity() {
  const changes=[...(state.data.changes||[])].sort((a,b)=>b.at.localeCompare(a.at));
  return `<article class="content-card"><h2>Tracker activity</h2><p>These timestamps show when the tracker detected a change. The official action date appears on each bill.</p>${changes.length?changes.map(c=>`<div class="activity-item"><time>${displayDate(c.at,true)}</time><div><button data-bill="${escapeHTML(c.id)}">${escapeHTML(state.data.bills.find(b=>b.id===c.id)?.number||c.id)}</button><span class="activity-kind">${escapeHTML(c.kind)}</span><p>${escapeHTML(c.detail)}</p></div></div>`).join(''):'<p>No detected changes in this snapshot.</p>'}</article>`;
}
function showBill(id, updateHash=true) {
  const b=state.data.bills.find(b=>b.id===id); if(!b){toast('That measure is not in this snapshot.');return;}
  const saved=local.saved.includes(id);
  $('#detail').innerHTML=`<div class="detail-header"><span>90R · ${escapeHTML(b.chamber.toUpperCase())} · ${b.type.includes('JR')?'JOINT RESOLUTION':b.type.endsWith('B')?'BILL':'RESOLUTION'}</span><button class="close" data-close aria-label="Close bill details">×</button></div><div class="detail-body"><span class="bill-number ${b.chamber==='Senate'?'senate':''}">${escapeHTML(b.number)}</span><h2 id="detail-title">${escapeHTML(b.title||b.caption)}</h2><p class="detail-author">Filed by ${escapeHTML(b.author)}</p><div>${b.topics.map(t=>`<span class="topic-tag">${escapeHTML(t)}</span>`).join('')}</div><div class="status-box"><span>LATEST OFFICIAL ACTION · ${displayDate(b.actionDate,true).toUpperCase()}</span><strong>${escapeHTML(b.lastAction)}</strong></div><span class="review-badge ${reviewed(b)?'':'pending'}">${reviewed(b)?'✓ ':''}${escapeHTML(b.reviewState)}</span><section class="detail-block"><h3>${reviewed(b)?'What the filed text would do':'Official caption'}</h3><p>${escapeHTML(b.summary||b.caption)}</p>${reviewed(b)?`<p class="hint">${escapeHTML(b.reviewVersion||'Introduced version')} · reviewed ${displayDate(b.reviewedAt,true)} · ${escapeHTML(b.sections||'See bill text')}</p>`:'<p class="hint">This is a screening match. Read the bill text before drawing conclusions about its effect.</p>'}</section>${b.relevance?`<section class="detail-block"><h3>Why it is on the radar · editorial assessment</h3><p>${escapeHTML(b.relevance)}</p></section>`:''}<section class="detail-block"><h3>Hearings & committee notices</h3><p>Follow hearing dates, official notices, agenda changes, and cancellations for this bill.</p><a class="button" href="/hearings/?bill=${encodeURIComponent(b.id)}">View notices for ${escapeHTML(b.number)} →</a></section><section class="detail-block"><h3>Go to the official record</h3><div class="source-links"><a href="${escapeHTML(b.historyUrl)}" target="_blank" rel="noopener">Bill history <span>→</span></a><a href="${escapeHTML(b.textPageUrl)}" target="_blank" rel="noopener">All text versions <span>→</span></a>${b.reviewedTextUrl?`<a href="${escapeHTML(b.reviewedTextUrl)}" target="_blank" rel="noopener">Reviewed version <span>→</span></a>`:''}${b.textUrl?`<a href="${escapeHTML(b.textUrl)}" target="_blank" rel="noopener">Last retrieved text <span>→</span></a>`:''}</div><p class="hint">Metadata checked ${displayDate(b.sourceCheckedAt,true)}. ${b.textFetchError?'The most recent text retrieval failed; use All text versions to check the current text.':b.textCheckedAt?`Text retrieved ${displayDate(b.textCheckedAt,true)}.`:'Automatic text refresh has not yet run for this measure.'}</p></section><div class="detail-actions"><button class="button ${saved?'':'primary'}" data-save="${id}">${saved?'★ Saved to watchlist':'☆ Add to watchlist'}</button><button class="button" data-copy="${id}">Copy brief</button><button class="button" data-link="${id}">Copy link</button></div><section class="detail-block"><h3>Your working note</h3><textarea id="bill-note" data-note="${id}" placeholder="Add a question, follow-up, or point to examine…" aria-label="Personal note for ${escapeHTML(b.number)}">${escapeHTML(local.notes[id]||'')}</textarea><div class="note-actions"><span id="note-status">Saved automatically on this browser only.</span></div></section></div>`;
  if(!$('#bill-dialog').open)$('#bill-dialog').showModal();
  if(updateHash)history.replaceState(null,'','#bill/'+id);
}
function closeDialog() {$('#bill-dialog').close();history.replaceState(null,'','#'+state.view);}
function saveBill(id) {
  if(!state.data.bills.some(b=>b.id===id))return;
  local.saved=local.saved.includes(id)?local.saved.filter(x=>x!==id):[...local.saved,id];persist();renderBills();
  if($('#bill-dialog').open)showBill(id,false);
  toast(local.saved.includes(id)?'Added to your watchlist.':'Removed from your watchlist.');
}
async function copy(text) {try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{toast('Clipboard access was blocked. Select the text and copy it manually.');}}
function download(name,content,type) {const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV() {
  const cell=value=>`"${String(value??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')}"`;
  const fields=['Bill','Author','Caption','Topics','Latest action','Action date','Review','Summary','Relevance assessment','History URL','Personal note'];
  const rows=filtered().map(b=>[b.number,b.author,b.caption,b.topics.join('; '),b.lastAction,b.actionDate,b.reviewState,b.summary,b.relevance,b.historyUrl,local.notes[b.id]||'']);
  download('texas-90r-religious-liberty.csv','\uFEFF'+[fields,...rows].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast(`Exported ${rows.length} measures.`);
}
document.addEventListener('click',e=>{
  const target=e.target.closest('button,a');if(!target)return;
  if(target.dataset.view){navigate(target.dataset.view);return;}
  if(target.dataset.save){saveBill(target.dataset.save);return;}
  if(target.dataset.bill){showBill(target.dataset.bill);return;}
  if(target.hasAttribute('data-close')){closeDialog();return;}
  if(target.dataset.page){state.page=Number(target.dataset.page);renderBills();$('.legislation').scrollIntoView({block:'start',behavior:'smooth'});return;}
  if(target.hasAttribute('data-clear')||target.id==='clear-filters'){clearFilters();return;}
  if(target.dataset.copy){const b=state.data.bills.find(b=>b.id===target.dataset.copy);copy(`${b.number} | 90R | ${b.author}\n${b.summary||b.caption}\n${b.relevance?'\nRelevance assessment: '+b.relevance+'\n':''}\nLatest action: ${b.lastAction} (${b.actionDate})\nReview: ${b.reviewState}\nSource checked: ${displayDate(b.sourceCheckedAt,true)}\n${b.historyUrl}`);return;}
  if(target.dataset.link){copy(location.href.split('#')[0]+'#bill/'+target.dataset.link);return;}
  if(target.hasAttribute('data-backup'))download('texas-liberty-watch-personal-backup.json',JSON.stringify({session:'90R',...local},null,2),'application/json');
});
document.addEventListener('input',e=>{if(e.target.matches('[data-note]')){local.notes[e.target.dataset.note]=e.target.value;$('#note-status').textContent=persist()?'Saved on this browser.':'Not saved: browser storage is unavailable.';}});
document.addEventListener('change',async e=>{
  if(e.target.id!=='restore-backup'||!e.target.files[0])return;
  try{const file=e.target.files[0];if(file.size>2000000)throw Error('The backup is too large.');const backup=JSON.parse(await file.text());if(backup.session!=='90R'||!Array.isArray(backup.saved)||!backup.notes||typeof backup.notes!=='object')throw Error('Use a 90R personal backup file.');const valid=id=>/^(HB|SB|HJR|SJR|HCR|SCR|HR|SR)\d+$/.test(id);local.saved=[...new Set([...local.saved,...backup.saved.filter(id=>typeof id==='string'&&valid(id))])];for(const [id,note] of Object.entries(backup.notes))if(valid(id)&&typeof note==='string')local.notes[id]=note;persist();setCounts();toast('Personal backup restored.');}catch(error){toast(error.message||'Could not read that backup.');}
});
$('#search').addEventListener('input',()=>{state.page=1;renderBills();});
for(const id of ['topic','chamber','review','sort'])$('#'+id).addEventListener('change',()=>{state.page=1;renderBills();});
$('#export').addEventListener('click',exportCSV);
$('#bill-dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#bill-dialog').addEventListener('click',e=>{if(e.target===$('#bill-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)closeDialog();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#bill-dialog').open){e.preventDefault();navigate('tracker');$('#search').focus();}});
function route(){const hash=decodeURIComponent(location.hash.slice(1));if(hash.startsWith('bill/')){navigate('tracker',false);showBill(hash.slice(5),false);}else{if($('#bill-dialog').open)$('#bill-dialog').close();navigate(hash||'tracker',false);}}
window.addEventListener('hashchange',()=>{if(state.data)route();});
async function init(){
  const date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  $('#today').textContent=displayDate(new Date().toISOString(),true);
  $('#session-phase').textContent=date<'2026-11-09'?'90R · Before prefiling':date<'2027-01-12'?'90R · Prefiling':date<='2027-05-31'?'90R · Regular session':'90R · After session';
  document.querySelectorAll('.calendar li').forEach(li=>li.classList.remove('current'));
  const milestones=[...document.querySelectorAll('.calendar li')].filter(li=>li.querySelector('time').dateTime<=date);if(milestones.length)milestones.at(-1).classList.add('current');
  try{const response=await fetch('data/bills.json',{cache:'no-cache'});if(!response.ok)throw Error('Snapshot could not be loaded.');const data=await response.json();if(data.session!=='90R'||!Array.isArray(data.bills))throw Error('Unexpected dataset.');state.data=data;
    const old=Date.now()-new Date(data.updatedAt).getTime()>36*3600000;
    $('#source-line').innerHTML=`<span class="source-dot"></span><span>${data.screenedCount.toLocaleString()} official captions screened</span><span>·</span><span>Checked ${displayDate(data.updatedAt,true)}</span><span>·</span><button data-view="methodology" class="${old?'stale':''}">${old?'Snapshot needs refresh':'Snapshot · update details'}</button>`;
    $('#topic').innerHTML='<option value="">All topics</option>'+[...new Set(data.bills.flatMap(b=>b.topics))].sort().map(t=>`<option>${escapeHTML(t)}</option>`).join('');route();setCounts();
  }catch(error){$('#source-line').textContent='Snapshot unavailable';$('#load-error').hidden=false;$('#load-error').textContent='The bill snapshot could not be loaded. Reload the page to try again. Official bill records remain available at capitol.texas.gov.';$('#tracker-content').hidden=true;}
}
init();

